<script setup lang="ts">
import type { Platform, ExpenseType } from '~/types/models'
const props = defineProps<{ table: 'platforms' | 'expense_types'; title: string }>()
const db = useDb(), rows = ref<(Platform | ExpenseType)[]>([])
const name = ref(''), editing = ref(''), draft = ref(''), error = ref(''), info = ref(''), busy = ref(false), loading = ref(true)
async function load() { loading.value = true; error.value = ''; try { rows.value = await (props.table === 'platforms' ? db.platforms() : db.expenseTypes()) } catch (value) { error.value = message(value) } finally { loading.value = false } }
onMounted(load)
async function perform(action: () => Promise<unknown>) { if (busy.value) return; busy.value = true; error.value = ''; info.value = ''; try { await action(); info.value = 'Cambios guardados.'; await load() } catch (value) { error.value = message(value) } finally { busy.value = false } }
async function add() { await perform(async () => { await db.addCatalog(props.table, name.value); name.value = '' }) }
async function rename() { await perform(async () => { await db.updateCatalog(props.table, editing.value, { name: draft.value }); editing.value = '' }) }
async function remove(id: string) { if (!confirm('¿Eliminar este elemento? Si está en uso debes desactivarlo para conservar el histórico.')) return; await perform(() => db.remove(props.table, id)) }
</script>
<template><section class="card panel"><h2>{{ title }}</h2><p v-if="error" class="alert danger" role="alert">{{ error }} <button class="button secondary small" @click="load">Actualizar</button></p><p v-if="info" class="alert success" role="status">{{ info }}</p><form class="inline-form" @submit.prevent="add"><label class="field grow">Nombre<input v-model.trim="name" required :placeholder="`Añadir a ${title.toLowerCase()}`" /></label><button class="button primary" :disabled="busy || loading" type="submit">Añadir</button></form><p v-if="loading" role="status">Cargando…</p><div v-for="row in rows" :key="row.id" class="setting-row"><form v-if="editing === row.id" class="inline-form grow" @submit.prevent="rename"><label class="field grow">Nuevo nombre<input v-model.trim="draft" required /></label><button class="button primary small" type="submit" :disabled="busy">Guardar</button><button class="button secondary small" type="button" @click="editing = ''">Cancelar</button></form><template v-else><span><b>{{ row.name }}</b><small v-if="!row.active" class="inactive-label">Desactivado</small></span><div class="action-row"><button class="button tiny secondary" :disabled="busy" @click="editing = row.id; draft = row.name">Renombrar</button><button class="button tiny secondary" :disabled="busy" @click="perform(() => db.updateCatalog(table, row.id, { active: !row.active }))">{{ row.active ? 'Desactivar' : 'Activar' }}</button><button class="button tiny danger-button" :disabled="busy" @click="remove(row.id)">Eliminar</button></div></template></div></section></template>
